#include <stdlib.h>
#include <string.h>

#include "rbtree.h"

/* Internal node/tree layout. NIL is represented by plain NULL (treated as
 * black wherever color is read), not a shared sentinel node. Nodes carry
 * an explicit parent pointer. */

typedef enum { RB_RED, RB_BLACK } rb_color_t;

typedef struct rb_node {
    char           *key;    /* owned copy */
    void           *value;  /* owned iff value_free != NULL, per contract */
    rb_color_t      color;
    struct rb_node *parent; /* NULL at root */
    struct rb_node *left;
    struct rb_node *right;
} rb_node_t;

struct rbtree {
    rb_node_t        *root; /* NULL = empty tree */
    size_t             size;
    rb_value_free_fn   value_free;
};

/* Stub implementations below are scaffolding so the header's contract
 * links and the demo driver compiles/runs. Each remaining body is a safe
 * placeholder to be replaced one function at a time (see CLAUDE.md:
 * "implement in small slices"). */

rbtree_t *rb_create(rb_value_free_fn value_free) {
    rbtree_t *t = malloc(sizeof(*t));
    if (t == NULL) {
        return NULL;
    }
    t->root = NULL;
    t->size = 0;
    t->value_free = value_free;
    return t;
}

int rb_insert(rbtree_t *t, const char *key, void *value) {
    (void)t;
    (void)key;
    (void)value;
    /* TODO(M1): BST insert + red-black fixup. */
    return -1;
}

void *rb_find(const rbtree_t *t, const char *key) {
    (void)t;
    (void)key;
    /* TODO(M1): BST search by strcmp order. */
    return NULL;
}

int rb_delete(rbtree_t *t, const char *key) {
    (void)t;
    (void)key;
    /* TODO(M2): delete + fixup. */
    return -1;
}

size_t rb_size(const rbtree_t *t) {
    return t->size;
}

static void foreach_subtree(const rb_node_t *node,
                            void (*fn)(const char *key, void *value, void *ctx),
                            void *ctx) {
    if (node == NULL) {
        return;
    }
    foreach_subtree(node->left, fn, ctx);
    fn(node->key, node->value, ctx);
    foreach_subtree(node->right, fn, ctx);
}

void rb_foreach(const rbtree_t *t,
                void (*fn)(const char *key, void *value, void *ctx),
                void *ctx) {
    foreach_subtree(t->root, fn, ctx);
}

int rb_validate(const rbtree_t *t) {
    (void)t;
    /* TODO(M1): check the red-black invariants listed in rbtree.h. */
    return 0;
}

static void destroy_subtree(rb_node_t *node, rb_value_free_fn value_free) {
    if (node == NULL) {
        return;
    }
    destroy_subtree(node->left, value_free);
    destroy_subtree(node->right, value_free);
    free(node->key);
    if (value_free != NULL) {
        value_free(node->value);
    }
    free(node);
}

void rb_destroy(rbtree_t *t) {
    if (t == NULL) {
        return;
    }
    destroy_subtree(t->root, t->value_free);
    free(t);
}

#ifndef RBTREE_H
#define RBTREE_H
#include <stddef.h>

/* Red-black tree keyed by C strings (strcmp order); values are opaque
 * void *. See CLAUDE.md for the full ownership contract. */

typedef struct rbtree rbtree_t;
typedef void (*rb_value_free_fn)(void *value);

/* Returns NULL on allocation failure.
 * value_free may be NULL (values not owned). */
rbtree_t *rb_create(rb_value_free_fn value_free);

/* Copies key (tree owns the copy).
 * Takes ownership of value ONLY on success.
 * Overwriting an existing key frees the old value via value_free.
 * Returns 0 on success, -1 on allocation failure (tree unchanged, value NOT
 * consumed; caller still owns it). */
int rb_insert(rbtree_t *t, const char *key, void *value);

/* Returns the value, or NULL if absent. Tree retains ownership. */
void *rb_find(const rbtree_t *t, const char *key);

/* Removes key; frees the key copy and the value.
 * Returns 0, or -1 if absent. */
int rb_delete(rbtree_t *t, const char *key);

size_t rb_size(const rbtree_t *t);

/* In-order traversal. */
void rb_foreach(const rbtree_t *t,
                void (*fn)(const char *key, void *value, void *ctx),
                void *ctx);

/* Returns 0 iff all red-black invariants hold:
 * root is black; no red node has a red child; every root-to-NIL path
 * crosses the same number of black nodes; in-order traversal is strictly
 * increasing under strcmp; rb_size matches the actual node count. */
int rb_validate(const rbtree_t *t);

/* Frees all nodes, key copies, and (if owned) values. NULL-safe. */
void rb_destroy(rbtree_t *t);

#endif

